elseif($userDataPage==='reservas'){$pageTitle='Mis reservas';$raw=firebaseRead(fn(FirebaseReadService $f)=>$f->collection('reservas'));$records=array_values(array_filter($raw,fn($r)=>is_array($r)&&(string)($r['usuarioId']??'')===$uid));}
else{$pageTitle='Mis promociones';$raw=firebaseRead(fn(FirebaseReadService $f)=>$f->collection('mensajes'));$records=array_values(array_filter($raw,fn($r)=>is_array($r)&&($r['activo']??false)===true));}
usort($records,fn($a,$b)=>(firebaseDate($b['fechaCreacion']??$b['fechaSolicitada']??null)?->getTimestamp()??0)<=>(firebaseDate($a['fechaCreacion']??$a['fechaSolicitada']??null)?->getTimestamp()??0));
