<?php if($userDataPage==='reservas'):?><section class="section section--cream reservation-workspace"><div class="container"><form class="form-card reservation-form" data-reservation-create data-endpoint="../api/user/reservations/create.php"><input type="hidden" name="csrf_token" value="<?=h(chichejCsrfToken())?>"><div><span class="eyebrow">Nueva solicitud</span><h2>Crear reserva</h2><p>La administración confirmará o rechazará la solicitud. Esto no garantiza disponibilidad.</p></div><label>Detalle<input name="detalle" minlength="3" maxlength="300" required></label><label>Fecha solicitada<input type="date" name="fechaSolicitada" min="<?=$now->format('Y-m-d')?>" max="<?=$now->modify('+2 years')->format('Y-m-d')?>" required></label><label>Cantidad<input type="number" name="cantidadSolicitada" min="1" max="10000" required></label><label>Lugar del evento<input name="lugarEvento" minlength="3" maxlength="160" required></label><button class="button button--primary" type="submit">Solicitar reserva</button><p class="form-status" data-reservation-status role="status" aria-live="polite"></p></form><?php $pending=array_values(array_filter($records,fn($r)=>reservationTransitionAllowed($r['estado']??null,'cancelar',false)));if($pending):?><div class="reservation-actions"><h2>Reservas que puedes cancelar</h2><?php foreach($pending as $r):$reservationId=(string)($r['reservaId']??$r['_id']??'');if($reservationId==='')continue;?><article><div><strong><?=h($r['detalle']??'Reserva CHICHEJ')?></strong><small><?=h($reservationId)?> · <?=h(displayDate($r['fechaSolicitada']??null))?></small></div><button class="button button--ghost" type="button" data-reservation-cancel data-endpoint="../api/user/reservations/cancel.php" data-csrf="<?=h(chichejCsrfToken())?>" data-reservation-id="<?=h($reservationId)?>">Cancelar reserva</button><p class="form-status" data-reservation-status role="status" aria-live="polite"></p></article><?php endforeach;?></div><?php endif;?></div></section><?php endif;?>
<main id="contenido" class="portal"><section class="portal-hero portal-hero--small"><div class="container"><span class="eyebrow eyebrow--light">Área privada</span><h1><?=h($pageTitle)?></h1><p>Información real asociada exclusivamente a tu identidad autenticada.</p></div></section><section class="section section--cream"><div class="container"><?php if(!$records):?><div class="empty-state"><span>◇</span><h2>Sin datos registrados</h2><p>No encontramos información asociada a tu cuenta.</p></div><?php else:?><section class="user-records" data-filter-scope><div class="admin-filterbar user-filterbar"><label class="admin-search">Buscar<input type="search" data-filter-search placeholder="<?= $userDataPage==='pedidos'?'Producto, ID o estado…':'Detalle, ID o estado…' ?>"></label><?php if($userDataPage!=='promociones'):?><label>Estado<select data-filter-key="status"><option value="">Todos</option><?php foreach(array_keys($statuses) as $status):?><option value="<?=h($status)?>"><?=h($status)?></option><?php endforeach;?></select></label><label>Período<select data-filter-key="period"><option value="all">Todos</option><option value="today">Hoy</option><option value="7days">Últimos 7 días</option><option value="month">Este mes</option><option value="year">Este año</option></select></label><?php endif;?><span data-filter-count><?=count($records)?> registros</span></div><div class="data-list user-data-scroll" tabindex="0" aria-label="<?=h($pageTitle)?>"><?php foreach($records as $r):$recordDate=$userDataPage==='reservas'?($r['fechaSolicitada']??$r['fechaCreacion']??null):($r['fechaCreacion']??null);$search=$userDataPage==='pedidos'?implode(' ',[$r['pedidoId']??$r['_id']??'',orderSummary($r),$r['estado']??'']):implode(' ',[$r['reservaId']??$r['_id']??'',$r['detalle']??'',$r['estado']??'']);?><article class="data-card" data-filter-row data-search="<?=h($search)?>" data-status="<?=h($r['estado']??'')?>" data-period="<?=h($periodTags($recordDate))?>"><?php if($userDataPage==='pedidos'):?><div class="data-card__head"><div><small>Pedido <?=h($r['pedidoId']??$r['_id']??'Sin ID')?></small><h2><?=h(orderSummary($r))?></h2></div><span><?=h($r['estado']??'Sin estado')?></span></div><dl><div><dt>Fecha</dt><dd><?=h(displayDate($r['fechaCreacion']??null))?></dd></div><div><dt>Total</dt><dd><?=h(money($r['total']??null))?></dd></div><div><dt>Pago</dt><dd><?=h($r['metodoPago']??'Sin datos')?> · <?=h($r['estadoPago']??'Sin datos')?></dd></div><div><dt>Origen</dt><dd><?=h(orderOrigin($r))?></dd></div></dl><?php elseif($userDataPage==='reservas'):?><div class="data-card__head"><div><small>Reserva <?=h($r['reservaId']??$r['_id']??'Sin ID')?></small><h2><?=h($r['detalle']??'Reserva CHICHEJ')?></h2></div><span><?=h($r['estado']??'Sin estado')?></span></div><dl><div><dt>Fecha solicitada</dt><dd><?=h(displayDate($r['fechaSolicitada']??null))?></dd></div><div><dt>Cantidad</dt><dd><?=h($r['cantidadSolicitada']??$r['cantidad']??'Sin datos')?></dd></div><div><dt>Lugar</dt><dd><?=h($r['lugarEvento']??'Sin datos')?></dd></div></dl><?php else:?><span class="eyebrow"><?=($r['tipo']??'informativo')==='promocion'?'Promoción':'Informativo'?></span><h2><?=h($r['titulo']??'Publicación CHICHEJ')?></h2><p><?=h($r['mensaje']??'')?></p><small><?=h(displayDate($r['fechaCreacion']??null))?></small><?php endif;?></article><?php endforeach;?></div><p class="admin-filter-empty" data-filter-empty hidden>No hay registros que coincidan con los filtros.</p></section><?php endif;?></div></section></main>
